public class BoxPrinter {

    public static void printBox(int width, int height) {
        for (int row = 0; row < height; row++) {
            StringBuilder line = new StringBuilder();
            for (int col = 0; col < width; col++) {
                line.append('*');
            }
            System.out.println(line.toString());
        }
    }
}
